import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
        header = next(reader, None)
        if header is None:
            return {"columns": [], "rows": []}
        rows = list(reader)
    finally:
        csv.field_size_limit(previous_limit)

    width = max([len(header)] + [len(row) for row in rows])
    used_names = set(header)
    for index in range(len(header), width):
        base = "column_{}".format(index + 1)
        name = base
        suffix = 2
        while name in used_names:
            name = "{}_{}".format(base, suffix)
            suffix += 1
        header.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": header, "rows": rows}
